export const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const pageNames={pl:{home:'Strona główna',article:'Artykuł',product:'Produkt / oferta',about:'O nas',contact:'Kontakt','404':'Strona 404'},en:{home:'Homepage',article:'Article',product:'Product / offer',about:'About',contact:'Contact','404':'404 page'}};
const words={pl:{home:'Strona główna',journal:'Odkrywaj',about:'O nas',contact:'Kontakt',explore:'Zobacz więcej',latest:'Ostatnio dodane',read:'Czytaj historię',back:'Wróć na stronę główną',notfound:'Ta ścieżka prowadzi donikąd.',nftext:'Strona mogła zmienić adres. Znajdź coś dla siebie na stronie głównej.',eyebrow:'Nowa perspektywa',collection:'Poznaj kolekcję',inquire:'Zapytaj o ofertę',details:'Przemyślane w każdym detalu.',aboutTitle:'Dobre rzeczy zaczynają się od ciekawości.',contactTitle:'Porozmawiajmy.',contactText:'Masz pomysł, pytanie lub chcesz rozpocząć współpracę? Napisz do nas.',aboutText:'Tworzymy miejsce dla ludzi, którzy cenią jakość i uważne wybory. Dzielimy się doświadczeniem, szukamy nowych perspektyw i dbamy o szczegóły.',articleText:'Warto czasem zwolnić i przyjrzeć się rzeczom, które otaczają nas każdego dnia. Najlepsze pomysły często zaczynają się od prostego pytania: co naprawdę jest dla nas ważne?',articleSub:'Małe zmiany, duża różnica',articleMore:'Zacznij od jednego elementu. Wybierz to, co odpowiada Twoim potrzebom, sprawdź to w praktyce i daj sobie czas na własne odkrycia. Nie chodzi o doskonałość, lecz o świadome decyzje.',sample:'Przykładowa oferta',price:'Wycena indywidualna',spec:'Szczegóły oferty',specText:'Zakres, wariant i termin ustalamy wspólnie. Skontaktuj się z nami, aby otrzymać informacje dopasowane do Twoich potrzeb.',next:'Starsze wpisy',previous:'Nowsze wpisy',comments:'Komentarze',comment:'Dodaj komentarz',empty:'Wkrótce pojawią się tu nowe wpisy.'},en:{home:'Home',journal:'Explore',about:'About',contact:'Contact',explore:'Explore more',latest:'Latest stories',read:'Read the story',back:'Back to homepage',notfound:'This path leads nowhere.',nftext:'This page may have moved. Find something new on our homepage.',eyebrow:'A fresh perspective',collection:'Explore the collection',inquire:'Ask about this offer',details:'Thoughtful in every detail.',aboutTitle:'Good things begin with curiosity.',contactTitle:'Let’s talk.',contactText:'Have an idea, a question or a project in mind? Get in touch.',aboutText:'We create a place for people who value quality and thoughtful choices. We share our experience, look for fresh perspectives and care about the details.',articleText:'Sometimes it helps to slow down and look closely at the things around us. The best ideas often start with a simple question: what really matters to us?',articleSub:'Small changes, a big difference',articleMore:'Start with one element. Choose what fits your needs, try it in practice and allow time for discovery. It is about making thoughtful decisions, one step at a time.',sample:'Sample offer',price:'Price on request',spec:'Offer details',specText:'Scope, options and timing are agreed together. Get in touch for information tailored to your needs.',next:'Older posts',previous:'Newer posts',comments:'Comments',comment:'Add a comment',empty:'New posts will appear here soon.'}};
export function config(t,o={}){return {brand:String(o.brand||t.name).slice(0,70),accent:/^#[0-9a-f]{6}$/i.test(o.accent)?o.accent:t.accent,font:['serif','sans'].includes(o.font)?o.font:t.font,email:/^[^\s<>"@]+@[^\s<>"@]+\.[^\s<>"@]+$/.test(o.email||'')?o.email:'hello@example.com'};}
export function themeCss(t,o={}){const c=config(t,o),dark=['tech','automotive','portfolio'].includes(t.layout);return `
:root{--accent:${c.accent};--paper:${t.bg};--ink:${dark?'#f5f5f1':'#22251f'};--muted:${dark?'#b9bcb9':'#62665e'};--line:${dark?'#ffffff26':'#22251f26'}}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button,input{font:inherit}img{width:100%;object-fit:cover;display:block}h1,h2,h3,p{margin-top:0}h1,h2,h3,.brand{font-family:${c.font==='serif'?'Georgia,serif':'Arial,sans-serif'};line-height:1.04}h1{font-size:clamp(38px,6vw,84px);font-weight:${c.font==='serif'?'400':'700'};letter-spacing:-.055em}h2{font-size:clamp(28px,4vw,46px);letter-spacing:-.04em}h3{font-size:25px}p{max-width:65ch}.wrap{max-width:1240px;margin:auto;padding:0 48px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:700}.site-header{display:flex;align-items:center;justify-content:space-between;gap:25px;min-height:100px;border-bottom:1px solid var(--line)}.brand{font-size:29px;font-weight:700;letter-spacing:-.04em}.site-nav{display:flex;gap:28px;align-items:center;font-size:14px}.pill{display:inline-block;padding:12px 24px;background:var(--ink);color:var(--paper);border:1px solid var(--ink);border-radius:0;text-decoration:none!important;font-size:14px;font-weight:700}.outline{background:transparent;color:var(--ink)}.hero{padding:58px 0;display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}.hero h1{margin:20px 0 24px}.hero p{color:var(--muted);max-width:39ch;margin-bottom:28px}.hero-img{height:520px}.hero-kicker{color:var(--accent)}.section-title{display:flex;justify-content:space-between;align-items:baseline;border-top:1px solid var(--line);padding-top:30px}.story-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin:22px 0 65px}.story img{height:230px;margin-bottom:20px}.story h3{margin:10px 0}.story p{color:var(--muted)}.site-footer{padding:36px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:24px;font-size:13px;color:var(--muted)}.page{padding:65px 0 85px}.page>h1{max-width:17ch}.page-image{height:480px;margin:28px 0}.prose{max-width:740px;margin:auto}.prose h2{margin-top:40px;font-size:32px}.prose p{font-size:18px}.detail{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.detail img{height:570px}.price{font-size:24px;color:var(--accent)}.error{text-align:center;padding:80px 20px}.error strong{font-size:130px;line-height:1;display:block;color:var(--accent)}.error p{margin:20px auto}.error h1{font-size:42px;margin-top:20px}.post-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px;margin:35px 0}.post-card{border-bottom:1px solid var(--line);padding-bottom:26px;min-width:0}.post-card img{height:240px}.post-card h2{font-size:30px;margin-top:20px}.post-body{overflow-wrap:anywhere}.post-body img{max-width:100%;height:auto}.post-body iframe{max-width:100%}.post-meta{font-size:13px;color:var(--muted)}.pagination{display:flex;justify-content:space-between;gap:20px;margin:35px 0}.comments{margin-top:45px;border-top:1px solid var(--line);padding-top:25px}.comment{padding:20px 0;border-bottom:1px solid var(--line)}.PageList ul{display:flex;gap:20px;flex-wrap:wrap;list-style:none;padding:0}.PageList h2{display:none}.contact-link{font-size:clamp(20px,4vw,42px);color:var(--accent);overflow-wrap:anywhere}.site-search{display:flex;gap:10px;margin:25px 0}.site-search input{min-width:0;max-width:350px;width:100%;padding:10px;background:var(--paper);color:var(--ink);border:1px solid var(--line)}
.layout-editorial .hero{grid-template-columns:.8fr 1.2fr}.layout-editorial .hero-img{border-radius:48% 48% 0 0}.layout-editorial .hero h1{font-style:italic}.layout-travel .hero{position:relative;display:block;padding:0;margin:32px 0 60px}.layout-travel .hero-img{height:650px}.layout-travel .hero-copy{position:absolute;inset:auto 48px 40px;z-index:1;color:white;max-width:700px}.layout-travel .hero:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent,#0009);pointer-events:none}.layout-travel .hero p,.layout-travel .hero-kicker{color:white}.layout-food .brand{color:var(--accent)}.layout-food .hero{grid-template-columns:1.1fr 1fr}.layout-food .hero-img{border-radius:50%;height:auto;aspect-ratio:1}.layout-food .hero h1{color:var(--accent)}.layout-food .pill{border-radius:30px}.layout-tech .hero{grid-template-columns:1.2fr 1fr}.layout-tech h1{text-transform:uppercase}.layout-tech .hero-img{clip-path:polygon(12% 0,100% 0,100% 88%,88% 100%,0 100%,0 12%)}.layout-tech .pill{background:var(--accent);color:#171b20;border-color:var(--accent)}.layout-fashion .brand{font-size:36px;letter-spacing:.15em}.layout-fashion .hero{padding:25px 0;gap:0;grid-template-columns:1fr 1fr}.layout-fashion .hero-copy{padding:30px 50px 30px 0}.layout-fashion .hero h1{font-size:clamp(45px,7vw,90px);text-transform:uppercase}.layout-fashion .hero-img{height:630px}.layout-magazine .site-header{border-bottom:4px solid var(--ink)}.layout-magazine .hero{display:grid;grid-template-columns:1.2fr 1fr;align-items:start}.layout-magazine .hero-copy{order:2}.layout-magazine .hero-img{height:480px}.layout-magazine .hero h1{font-size:clamp(40px,5vw,68px)}.layout-magazine .eyebrow{color:var(--accent)}.layout-shop .hero{gap:0;background:#e7dfd3;margin:35px 0 50px;padding:0}.layout-shop .hero-copy{padding:48px}.layout-shop .hero-img{height:550px}.layout-shop .hero h1{font-weight:400}.layout-digital .hero{position:relative;gap:20px}.layout-digital .hero-img{height:500px;border-radius:140px 140px 30px 30px}.layout-digital h1{color:var(--accent)}.layout-digital .pill{border-radius:12px;background:var(--accent);border-color:var(--accent);color:white}.layout-automotive .hero{display:flex;flex-direction:column;align-items:stretch;gap:15px}.layout-automotive .hero-copy{display:grid;grid-template-columns:1.3fr 1fr;gap:0 35px}.layout-automotive .hero-kicker{grid-column:1/-1}.layout-automotive .hero h1{grid-row:2/4;margin:0;font-style:italic;text-transform:uppercase}.layout-automotive .hero-img{height:470px}.layout-automotive .pill{background:var(--accent);border-color:var(--accent);color:#151515;justify-self:start}.layout-outdoor .hero{grid-template-columns:1fr 1.1fr}.layout-outdoor .hero h1{text-transform:uppercase;line-height:.95}.layout-outdoor .hero-img{transform:rotate(2deg);border:12px solid white;box-shadow:0 10px 30px #0001}.layout-outdoor .pill{background:var(--accent);border-color:var(--accent);color:#222}.layout-service .hero{grid-template-columns:1fr 1.2fr;align-items:end}.layout-service .hero-img{height:620px}.layout-service .hero h1{font-weight:400}.layout-service .brand{font-size:22px;text-transform:uppercase;letter-spacing:.14em}.layout-portfolio .hero{grid-template-columns:1.2fr .8fr;padding-top:30px}.layout-portfolio .hero h1{font-size:clamp(50px,8vw,108px);font-weight:400}.layout-portfolio .hero-img{height:620px;filter:grayscale(1)}.layout-portfolio .brand{font-weight:400}.layout-portfolio .story-grid{grid-template-columns:1fr 1fr}.layout-portfolio .story img{height:400px;filter:grayscale(1)}
@media(max-width:700px){.wrap{padding:0 22px}.site-header{padding:20px 0;display:block}.site-nav{margin-top:20px;gap:17px;flex-wrap:wrap}.brand{font-size:26px}.hero,.layout-editorial .hero,.layout-food .hero,.layout-tech .hero,.layout-fashion .hero,.layout-magazine .hero,.layout-shop .hero,.layout-outdoor .hero,.layout-service .hero,.layout-portfolio .hero{grid-template-columns:1fr;gap:25px;padding:30px 0}.hero-img,.layout-service .hero-img,.layout-portfolio .hero-img,.layout-fashion .hero-img{height:380px}.layout-travel .hero-copy{inset:auto 25px 30px}.layout-travel .hero-img{height:570px}.layout-fashion .hero-copy,.layout-shop .hero-copy{padding:25px}.layout-magazine .hero-copy{order:0}.layout-automotive .hero-copy{display:block}.layout-automotive .hero h1{margin-bottom:20px}.story-grid,.post-list{grid-template-columns:1fr}.layout-portfolio .story-grid{grid-template-columns:1fr}.detail{grid-template-columns:1fr;gap:30px}.detail img{height:380px}.page-image{height:300px}.site-footer{flex-direction:column}.page{padding:40px 0}.error strong{font-size:100px}}`;
}
function picture(t,cl='hero-img'){return `<img class="${cl}" src="${escapeHtml(t.image)}" alt="${escapeHtml(t.topic.en)}" loading="eager" />`;}
function hero(t,l,o={}){const w=words[l],c=config(t,o);return `<section class="hero"><div class="hero-copy"><span class="eyebrow hero-kicker">${escapeHtml(t.topic[l])} / ${w.eyebrow}</span><h1>${escapeHtml(t.headline[l])}</h1><p>${escapeHtml(t.description[l])}</p><a class="pill" href="/search" data-page="${['shop','rental'].includes(t.category)?'product':'article'}">${['shop','rental'].includes(t.category)?w.collection:w.explore} &#8599;</a></div>${picture(t)}</section>`;}
export function pageContent(t,page='home',l='pl',o={}){const w=words[l],c=config(t,o);if(page==='home')return hero(t,l,o)+`<div class="section-title"><h2>${w.latest}</h2><span class="eyebrow">01 — 03</span></div><div class="story-grid">${[t.article[l],w.details,w.aboutTitle].map((h,i)=>`<article class="story"><a href="${i===2?'/p/about.html':'/search'}" data-page="${i===2?'about':'article'}">${picture(t,'story-img')}<span class="eyebrow">0${i+1} / ${escapeHtml(t.topic[l])}</span><h3>${escapeHtml(h)}</h3><p>${escapeHtml(t.description[l])}</p></a></article>`).join('')}</div>`;
if(page==='404')return `<section class="error"><strong>404</strong><h1>${w.notfound}</h1><p>${w.nftext}</p><a class="pill" href="/" data-page="home">${w.back}</a></section>`;
if(page==='contact')return `<section class="page"><span class="eyebrow">${w.contact}</span><h1>${w.contactTitle}</h1><p>${w.contactText}</p><a class="contact-link" href="mailto:${escapeHtml(c.email)}">${escapeHtml(c.email)} &#8599;</a></section>`;
if(page==='about')return `<section class="page"><span class="eyebrow">${w.about} / ${escapeHtml(c.brand)}</span><h1>${w.aboutTitle}</h1>${picture(t,'page-image')}<div class="prose"><h2>${escapeHtml(t.headline[l])}</h2><p>${w.aboutText}</p><p>${escapeHtml(t.description[l])}</p><a class="pill" href="/p/contact.html" data-page="contact">${w.contact}</a></div></section>`;
if(page==='product')return `<section class="page detail">${picture(t,'product-image')}<div><span class="eyebrow">${escapeHtml(t.topic[l])} / 001</span><h1>${w.details}</h1><p>${escapeHtml(t.description[l])}</p><p class="price">${w.price}</p><a class="pill" href="mailto:${escapeHtml(c.email)}?subject=${encodeURIComponent(c.brand+' — '+w.sample)}">${w.inquire} &#8599;</a><h3 style="margin-top:40px">${w.spec}</h3><p>${w.specText}</p></div></section>`;
return `<article class="page"><div class="prose"><span class="eyebrow">${escapeHtml(t.topic[l])} / ${l==='pl'?'5 minut czytania':'5 min read'}</span><h1>${escapeHtml(t.article[l])}</h1><p>${escapeHtml(t.description[l])}</p></div>${picture(t,'page-image')}<div class="prose"><p>${w.articleText}</p><h2>${w.articleSub}</h2><p>${w.articleMore}</p><blockquote>${escapeHtml(t.headline[l])}</blockquote><p>${w.articleText}</p><a href="/" data-page="home">&#8592; ${w.back}</a></div></article>`;
}
export function renderPreview(t,page='home',l='pl',o={}){const c=config(t,o),w=words[l];return `<!doctype html><html lang="${l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(c.brand)}</title><style>${themeCss(t,o)}</style></head><body class="layout-${t.layout}"><div class="wrap"><header class="site-header"><a class="brand" href="/" data-page="home">${escapeHtml(c.brand)}</a><nav class="site-nav"><a href="/search" data-page="article">${w.journal}</a><a href="/p/about.html" data-page="about">${w.about}</a><a href="/p/contact.html" data-page="contact">${w.contact} &#8599;</a></nav></header><main>${pageContent(t,page,l,o)}</main><footer class="site-footer"><span>© ${escapeHtml(c.brand)}</span><span>${escapeHtml(t.topic[l])} · ${w.eyebrow}</span><a href="/p/contact.html" data-page="contact">${w.contact}</a></footer></div><script>document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;if(a.dataset.page){e.preventDefault();parent.postMessage({type:'forma-page',page:a.dataset.page},'*');}else if(a.href.startsWith('mailto:')){e.preventDefault();parent.postMessage({type:'forma-contact'},'*');}});</script></body></html>`;}
export function renderBlogger(t,l='pl',o={}){const c=config(t,o),w=words[l];const css=themeCss(t,o).replace(/\]\]>/g,']]]]><![CDATA[>');return `<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE html>
<html b:version="2" expr:dir="data:blog.languageDirection" lang="${l}" xmlns="http://www.w3.org/1999/xhtml" xmlns:b="http://www.google.com/2005/gml/b" xmlns:data="http://www.google.com/2005/gml/data" xmlns:expr="http://www.google.com/2005/gml/expr">
<head><meta content="width=device-width, initial-scale=1" name="viewport"/><b:include data="blog" name="all-head-content"/><title><data:blog.pageTitle/></title><b:skin><![CDATA[${css}]]></b:skin></head>
<body class="layout-${t.layout}"><div class="wrap"><header class="site-header"><a class="brand" expr:href="data:blog.homepageUrl">${escapeHtml(c.brand)}</a><nav class="site-nav"><a expr:href='data:blog.homepageUrl + "search"'>${w.journal}</a><a href="/p/about.html">${w.about}</a><a href="/p/contact.html">${w.contact} &#8599;</a></nav></header>
<b:section id="pages" class="navbar" maxwidgets="1" showaddelement="yes"><b:widget id="PageList1" locked="false" title="${w.journal}" type="PageList"/></b:section>
<main><b:if cond='data:blog.pageType == "error_page"'>${pageContent(t,'404',l,o)}<b:else/>
<b:if cond='data:blog.url == data:blog.homepageUrl'>${hero(t,l,o)}<div class="section-title"><h2>${w.latest}</h2></div></b:if>
<b:section id="main" class="main" maxwidgets="1" showaddelement="no"><b:widget id="Blog1" locked="true" title="Blog Posts" type="Blog" version="1"><b:includable id="main" var="top">
<b:if cond='data:blog.pageType == "item" or data:blog.pageType == "static_page"'>
<b:loop values="data:posts" var="post"><article class="page"><b:if cond='data:blog.pageType == "item"'><div class="prose"><h1><data:post.title/></h1><p class="post-meta"><data:post.author/> · <data:post.timestamp/></p></div></b:if><div class="post-body"><data:post.body/></div><b:if cond='data:post.allowComments'><section class="comments prose"><h2>${w.comments}</h2><b:loop values="data:post.comments" var="comment"><div class="comment"><strong><data:comment.author/></strong><div><data:comment.body/></div></div></b:loop><a class="pill outline" expr:href="data:post.addCommentUrl">${w.comment}</a></section></b:if></article></b:loop>
<b:else/><div class="post-list"><b:loop values="data:posts" var="post"><article class="post-card"><b:if cond="data:post.firstImageUrl"><a expr:href="data:post.url"><img expr:src="data:post.firstImageUrl" expr:alt="data:post.title" loading="lazy"/></a></b:if><h2><a expr:href="data:post.url"><data:post.title/></a></h2><p class="post-meta"><data:post.timestamp/></p><p><data:post.snippet/></p><a expr:href="data:post.url">${w.read} &#8599;</a></article></b:loop></div>
<b:if cond="data:posts.empty"><p>${w.empty}</p></b:if><nav class="pagination"><b:if cond="data:newerPageUrl"><a expr:href="data:newerPageUrl">&#8592; ${w.previous}</a></b:if><b:if cond="data:olderPageUrl"><a expr:href="data:olderPageUrl">${w.next} &#8594;</a></b:if></nav></b:if>
</b:includable></b:widget></b:section></b:if></main>
<footer class="site-footer"><span>© ${escapeHtml(c.brand)}</span><span>${escapeHtml(t.topic[l])}</span><a href="/p/contact.html">${w.contact}</a></footer></div></body></html>`;}
export function installGuide(t,l='pl',o={}){const c=config(t,o);return l==='pl'?`FORMA THEMES — ${c.brand}\nWersja ${t.version}\n\n1. W Bloggerze wykonaj kopię obecnego motywu (Motyw → menu → Kopia zapasowa).\n2. Motyw → menu → Edytuj kod HTML: zastąp kod zawartością theme.xml i zapisz. Możesz też użyć opcji przywrócenia XML.\n3. Wyłącz osobny motyw mobilny Bloggera, jeżeli jest aktywny. Ten motyw jest responsywny.\n4. Strony → Nowa strona. Najpierw utwórz stronę o tytule „about”, aby uzyskać /p/about.html. W widoku HTML wklej pages/about.html. Po publikacji zmień tytuł na „O nas”. Analogicznie utwórz „contact” (/p/contact.html). Sprawdź adresy: jeśli Blogger nadał inne, zmień dwa linki w XML.\n5. Wpisy → Nowy wpis → widok HTML: użyj content/article.html lub content/product.html. To treści startowe; zastąp je własnymi. Dla wpisu produktu możesz użyć etykiety Produkty. Strona główna, etykiety /search/label/Produkty i wyszukiwarka /search?q= renderują Twoje wpisy.\n6. Ustaw tytuły wpisów, zdjęcia i opisy. Lista na stronie głównej pochodzi z opublikowanych wpisów, nie z demonstracyjnych kart galerii.\n7. Strona 404 jest wbudowana. Sprawdź ją pod nieistniejącym adresem.\n8. Ustaw swój e-mail przed eksportem lub zastąp hello@example.com w stronie Kontakt i ofercie. Aktualny adres: ${c.email}.\n9. Sprawdź podstrony, paginację i komentarze na testowym blogu przed użyciem produkcyjnym. XML sprawdzono strukturalnie; import do konkretnego konta Blogger wymaga testu.\n\nW MVP sklep/wypożyczalnia jest katalogiem z zapytaniem mailowym. Brak koszyka, płatności i kalendarza rezerwacji.\nZdjęcia demonstracyjne: Unsplash, źródło ${t.source}. Przed publikacją możesz zastąpić je własnymi.\nDokumentacja: https://support.google.com/blogger/answer/176245 i https://support.google.com/blogger/answer/165955\n`:`FORMA THEMES — ${c.brand}\nVersion ${t.version}\n\n1. Back up your current theme in Blogger (Theme → menu → Backup).\n2. Theme → menu → Edit HTML: replace the code with theme.xml and save, or restore the XML file.\n3. Disable a separate Blogger mobile theme if enabled; this theme is responsive.\n4. Create a page titled "about" to obtain /p/about.html. Paste pages/about.html in HTML view, publish, then rename its title to About. Repeat for "contact" (/p/contact.html). Verify the resulting URLs and adjust the two XML links if needed.\n5. Create posts in HTML view using content/article.html or content/product.html. Replace all demo copy. Product posts can use a Products label. The homepage, label pages and /search?q= render your published posts.\n6. Add your own post titles, images and descriptions. Homepage cards come from published posts, not the preview's sample cards.\n7. The 404 layout is built in; test it with a nonexistent URL.\n8. Set your email before exporting or replace hello@example.com in Contact and offer content. Current email: ${c.email}.\n9. Test pages, pagination and comments on a test blog before production. XML has structural checks; import into your Blogger account still needs verification.\n\nMVP shops/rentals are inquiry catalogs. No cart, payment or availability calendar.\nDemo photo: Unsplash, source ${t.source}. You can replace it with your own.\nDocs: https://support.google.com/blogger/answer/176245 and https://support.google.com/blogger/answer/165955\n`;}
export function packageFiles(t,l='pl',o={}){const files={'theme.xml':renderBlogger(t,l,o),'INSTALL.txt':installGuide(t,l,o),'pages/about.html':pageContent(t,'about',l,o),'pages/contact.html':pageContent(t,'contact',l,o),'content/article.html':pageContent(t,'article',l,o).replace(/<h1>[\s\S]*?<\/h1>/,''),'content/product.html':pageContent(t,'product',l,o)};for(const page of t.pages){files[`preview/${page}.html`]=renderPreview(t,page,l,o).replace(/<script>[\s\S]*?<\/script>/,'').replace(/href="[^"]*" data-page="([^"]+)"/g,'href="$1.html"');}return files;}
